@org.springframework.test.annotation.DirtiesContext
@Testcontainers
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"registration.privacy-approved=true","security.data-key=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","security.search-key=AQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQE=","security.signing-key=AgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgI=","registration.attempts-per-minute=1000","registration.global-attempts-per-minute=5000"})
class AssignmentFlowTest {
    @Container static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:17.6");
    @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",POSTGRES::getJdbcUrl);r.add("spring.datasource.username",POSTGRES::getUsername);r.add("spring.datasource.password",POSTGRES::getPassword);}
    @LocalServerPort int port;@Autowired JdbcTemplate jdbc;@Autowired DataProtector protector;@Autowired ObjectMapper json;@MockBean PaymentProvider payments;
    final HttpClient client=HttpClient.newHttpClient();static final String PASS="Senha-sintetica-123";UUID tariff,cancellation,assignmentPolicy,unit,protocol;
    @BeforeEach void policies(){tariff=UUID.randomUUID();cancellation=UUID.randomUUID();assignmentPolicy=UUID.randomUUID();unit=UUID.randomUUID();protocol=UUID.randomUUID();jdbc.update("INSERT INTO tarifa(id,numero,formula_codigo,parametros,inicio,estado) VALUES (?,?, 'BASE_KM_MINUTO','{}',clock_timestamp(),'ATIVA')",tariff,uniqueNumber());jdbc.update("INSERT INTO politica_cancelamento(id,numero,criterios,inicio,estado) VALUES (?,?, '{}',clock_timestamp(),'ATIVA')",cancellation,uniqueNumber());jdbc.update("INSERT INTO politica_designacao(id,numero,limite_tarefas_simultaneas,inicio,estado) VALUES (?,?,1,clock_timestamp(),'ATIVA')",assignmentPolicy,uniqueNumber());jdbc.update("INSERT INTO protocolo_custodia(id,unidade_id,numero,regras,cobertura_retorno_confirmada,inicio,estado) VALUES (?,?,1,'{}',true,clock_timestamp(),'HABILITADO')",protocol,unit);}

    @Test void concurrentDriversOnlyCreateOneAuditedAssignmentAndProtectTaskData()throws Exception{
        Account patient=account("patient-a"),first=account("driver-a"),second=account("driver-b"),outsider=account("driver-c");Driver d1=driver(first),d2=driver(second);driver(outsider);Covered order=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA");
        assertThat(offerIds(first)).contains(order.order);String offerJson=request(first,"GET","/offers",null,null,null).body();assertThat(offerJson).doesNotContain("Rua exata",patient.user.toString()).contains("Cidade origem","Cidade destino");
        try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->accept(first,order,d1.link,"same-order-a").statusCode());var b=pool.submit(()->accept(second,order,d2.link,"same-order-b").statusCode());assertThat(List.of(a.get(),b.get())).containsExactlyInAnyOrder(201,412);}
        assertThat(jdbc.queryForObject("SELECT count(*) FROM designacao WHERE pedido_id=? AND encerrada_em IS NULL",Long.class,order.order)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM evento_designacao WHERE pedido_id=? AND tipo='ACEITE'",Long.class,order.order)).isEqualTo(1);
        UUID assignedUser=jdbc.queryForObject("SELECT e.usuario_id FROM designacao d JOIN entregador e ON e.id=d.entregador_id WHERE d.pedido_id=?",UUID.class,order.order);Account assigned=assignedUser.equals(first.user)?first:second,notAssigned=assignedUser.equals(first.user)?second:first;
        assertThat(request(assigned,"GET","/orders/"+order.order+"/addresses",null,null,null).statusCode()).isEqualTo(200);assertThat(request(notAssigned,"GET","/orders/"+order.order+"/addresses",null,null,null).statusCode()).isEqualTo(404);assertThat(request(outsider,"GET","/orders/"+order.order+"/assignment",null,null,null).statusCode()).isEqualTo(404);
        var identity=request(patient,"GET","/orders/"+order.order+"/driver",null,null,null);assertThat(identity.statusCode()).isEqualTo(200);assertThat(identity.body()).contains("Entregador sintético","ABC").doesNotContain("cpf","cnh","renda","beneficio");
    }

    @Test void capacityReplayVersionAndApprovalAreRecheckedInsideTransaction()throws Exception{
        Account patient=account("patient-b"),courier=account("driver-limit");Driver driver=driver(courier);Covered first=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA"),second=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA");
        try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->accept(courier,first,driver.link,"limit-a"));var b=pool.submit(()->accept(courier,second,driver.link,"limit-b"));var responses=List.of(a.get(),b.get());assertThat(responses.stream().map(HttpResponse::statusCode).toList()).containsExactlyInAnyOrder(201,409);HttpResponse<String> won=responses.stream().filter(x->x.statusCode()==201).findFirst().orElseThrow();Covered accepted=won.body().contains(first.order.toString())?first:second;String key=accepted==first?"limit-a":"limit-b";var replay=accept(courier,accepted,driver.link,key);assertThat(replay.statusCode()).isEqualTo(201);assertThat(body(replay).get("id")).isEqualTo(body(won).get("id"));}
        Covered stale=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA");assertThat(request(courier,"POST","/orders/"+stale.order+"/assignment",task(driver.link),"stale",String.valueOf(stale.version-1)).statusCode()).isEqualTo(412);
        jdbc.update("UPDATE designacao SET encerrada_em=clock_timestamp(),encerramento_motivo='TESTE' WHERE entregador_id=?",driver.driver);jdbc.update("UPDATE entregador SET estado='SUSPENSO' WHERE id=?",driver.driver);Covered blocked=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA");assertThat(accept(courier,blocked,driver.link,"approval-lost").statusCode()).isEqualTo(403);assertThat(request(courier,"GET","/me/assignments",null,null,null).statusCode()).isEqualTo(200);
        jdbc.update("UPDATE entregador SET estado='APROVADO' WHERE id=?",driver.driver);jdbc.update("UPDATE vinculo_veiculo SET estado='SUSPENSO' WHERE id=?",driver.link);assertThat(accept(courier,blocked,driver.link,"link-lost").statusCode()).isEqualTo(403);
    }

    @Test void onlyEffectiveCoverageOffersAndInvalidationRacesCannotCreateStaleAssignment()throws Exception{
        Account patient=account("patient-c"),courier=account("driver-coverage");Driver driver=driver(courier);
        Covered confirmed=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA"),pending=covered(patient,"PENDENTE",BigDecimal.ZERO,"RESERVADA"),uncertain=covered(patient,"INCERTA",BigDecimal.ZERO,"RESERVADA"),insufficient=covered(patient,null,new BigDecimal("38.00"),"INSUFICIENTE"),released=covered(patient,null,new BigDecimal("38.00"),"LIBERADA");List<UUID> offers=offerIds(courier);assertThat(offers).contains(confirmed.order).doesNotContain(pending.order,uncertain.order,insufficient.order,released.order);
        Covered addressRace=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA");try(var pool=Executors.newFixedThreadPool(2)){var accept=pool.submit(()->accept(courier,addressRace,driver.link,"address-race").statusCode());var change=pool.submit(()->request(patient,"PUT","/orders/"+addressRace.order+"/addresses",json.writeValueAsString(Map.of("origin",address("Cidade nova"),"destination",address("Destino novo"),"version",addressRace.version)),null,null).statusCode());List<Integer> result=List.of(accept.get(),change.get());assertThat(result).isIn(List.of(201,412),List.of(412,201),List.of(409,200),List.of(200,409));}
        jdbc.update("UPDATE designacao SET encerrada_em=clock_timestamp(),encerramento_motivo='TESTE' WHERE entregador_id=? AND encerrada_em IS NULL",driver.driver);
        Covered cancelRace=covered(patient,"CONFIRMADA",BigDecimal.ZERO,"RESERVADA");try(var pool=Executors.newFixedThreadPool(2)){var accept=pool.submit(()->accept(courier,cancelRace,driver.link,"cancel-race").statusCode());var cancel=pool.submit(()->request(patient,"POST","/orders/"+cancelRace.order+"/cancel","{\"reasonCode\":\"TESTE\"}","cancel-race",String.valueOf(cancelRace.version)).statusCode());List<Integer> result=List.of(accept.get(),cancel.get());assertThat(result).isIn(List.of(201,412),List.of(412,201),List.of(409,200),List.of(200,409));}
        jdbc.update("UPDATE designacao SET encerrada_em=clock_timestamp(),encerramento_motivo='TESTE' WHERE entregador_id=? AND encerrada_em IS NULL",driver.driver);
        Covered late=covered(patient,"PENDENTE",BigDecimal.ZERO,"RESERVADA");UUID op=jdbc.queryForObject("SELECT id FROM operacao_financeira WHERE pedido_id=? AND tipo='COBRANCA'",UUID.class,late.order);jdbc.update("UPDATE pedido SET estado='EM_VERIFICACAO',version=version+1 WHERE id=?",late.order);jdbc.update("UPDATE orcamento SET estado='SUBSTITUIDO' WHERE pedido_id=?",late.order);when(payments.configured()).thenReturn(true);when(payments.providerId()).thenReturn("controlled-assignment-test");when(payments.authenticateAndParse(any(),any())).thenReturn(new PaymentProvider.PaymentEvent("late",op,PaymentProvider.Result.CONFIRMED,new BigDecimal("38.00"),"BRL",late.patient.toString(),Instant.now()));assertThat(event("late-event").statusCode()).isEqualTo(202);assertThat(jdbc.queryForObject("SELECT estado FROM pedido WHERE id=?",String.class,late.order)).isEqualTo("EM_VERIFICACAO");assertThat(offerIds(courier)).doesNotContain(late.order);
    }

    private Account account(String prefix)throws Exception{UUID id=UUID.randomUUID();String email=prefix+id+"@example.test";jdbc.update("INSERT INTO usuario(id,email_cifrado,email_busca,senha_hash,nome_cifrado,estado,email_verificado_em) VALUES (?,?,?,?,?,'ATIVO',clock_timestamp())",id,protector.encrypt(email),protector.lookup(email),Passwords.hash(PASS),protector.encrypt(prefix.startsWith("driver")?"Entregador sintético":"Paciente sintético"));var login=request(null,"POST","/auth/login",json.writeValueAsString(Map.of("email",email,"password",PASS,"client","MOBILE")),null,null);return new Account(id,body(login).get("accessToken").toString());}
    private Driver driver(Account a){UUID photo=UUID.randomUUID(),driver=UUID.randomUUID(),vehicle=UUID.randomUUID(),link=UUID.randomUUID();String plate="ABC"+String.format("%04d",Math.abs(uniqueNumber())%10000);jdbc.update("INSERT INTO documento(id,proprietario_id,categoria,objeto_chave,sha256,mime,tamanho,estado) VALUES (?,?,'FOTO_OPERACIONAL',?,'12345678901234567890123456789012','image/jpeg',100,'INSPECAO_APROVADA')",photo,a.user,"synthetic/"+photo);jdbc.update("INSERT INTO entregador(id,usuario_id,nascimento,estado,foto_aprovada_id) VALUES (?,?,DATE '1990-01-01','APROVADO',?)",driver,a.user,photo);jdbc.update("INSERT INTO veiculo(id,placa,marca,modelo,cor,ano_fabricacao,ano_modelo,estado) VALUES (?,?, 'Marca','Modelo','Azul',2024,2025,'APROVADO')",vehicle,plate);jdbc.update("INSERT INTO vinculo_veiculo(id,entregador_id,veiculo_id,tipo,estado,valido_ate,version) VALUES (?,?,?,'PROPRIEDADE','APROVADO',current_date+10,1)",link,driver,vehicle);return new Driver(driver,link);}
    private Covered covered(Account patient,String paymentState,BigDecimal subsidy,String reservationState){UUID patientId=patient(patient),doc=UUID.randomUUID(),order=UUID.randomUUID(),auth=UUID.randomUUID(),quote=UUID.randomUUID(),acceptance=UUID.randomUUID();byte[] origin=protect(address("Cidade origem")),destination=protect(address("Cidade destino"));jdbc.update("INSERT INTO documento(id,proprietario_id,categoria,objeto_chave,sha256,mime,tamanho,estado) VALUES (?,?,'AUTORIZACAO_RETIRADA',?,'12345678901234567890123456789012','application/pdf',100,'QUARENTENA')",doc,patient.user,"synthetic/"+doc);jdbc.update("INSERT INTO pedido(id,paciente_id,solicitante_id,origem_cifrada,destino_cifrada,origem_lat,origem_lon,destino_lat,destino_lon,destinatario_id,unidade_id,protocolo_id,estado,version) VALUES (?,?,?,?,?,-23.55,-46.63,-22.90,-43.17,?,?,?,'DISPONIVEL',2)",order,patientId,patient.user,origin,destination,patient.user,unit,protocol);jdbc.update("INSERT INTO autorizacao_retirada(id,pedido_id,documento_id,estado,criada_por,valida_ate) VALUES (?,?,?,'VERIFICADA',?,clock_timestamp()+interval '1 day')",auth,order,doc,patient.user);BigDecimal patientAmount=new BigDecimal("38.00").subtract(subsidy);UUID program=null;if(subsidy.signum()>0){UUID institution=UUID.randomUUID();program=UUID.randomUUID();jdbc.update("INSERT INTO instituicao(id,nome,estado) VALUES (?,'I','HABILITADA')",institution);jdbc.update("INSERT INTO programa(id,instituicao_id,codigo,nome,estado) VALUES (?,?,'P','P','HABILITADO')",program,institution);}jdbc.update("INSERT INTO orcamento(id,pedido_id,paciente_id,tarifa_id,rota_provedor,rota_referencia,distancia_m,duracao_s,rota_calculada_em,transito_incluido,politica_snapshot,frete,paciente_valor,subsidio_valor,moeda,expira_em,aceito_em,estado,programa_id,politica_cancelamento_id,pedido_version,version) VALUES (?,?,?,?,'route','ref',10000,1200,clock_timestamp(),false,'{}',38,?,?,'BRL',clock_timestamp()+interval '1 hour',clock_timestamp(),'ACEITO',?,?,1,1)",quote,order,patientId,tariff,patientAmount,subsidy,program,cancellation);jdbc.update("INSERT INTO aceite_orcamento(id,orcamento_id,pedido_id,paciente_id,aceito_por,pedido_version,orcamento_version,condicoes_snapshot,frete,paciente_valor,subsidio_valor,moeda) VALUES (?,?,?,?,?,1,0,'{}',38,?,?,'BRL')",acceptance,quote,order,patientId,patient.user,patientAmount,subsidy);if(patientAmount.signum()>0){jdbc.update("INSERT INTO operacao_financeira(id,pedido_id,tipo,chave_negocio,valor,moeda,estado,provedor,beneficiario_referencia) VALUES (?,?,'COBRANCA',?,?,'BRL',?,'test',?)",UUID.randomUUID(),order,"charge:"+order,patientAmount,paymentState,patientId.toString());}if(subsidy.signum()>0){UUID reservation=UUID.randomUUID();BigDecimal value="INSUFICIENTE".equals(reservationState)?subsidy.subtract(BigDecimal.ONE):subsidy;String state="LIBERADA".equals(reservationState)?"LIBERADA":"RESERVADA";BigDecimal released="LIBERADA".equals(reservationState)?value:BigDecimal.ZERO;jdbc.update("INSERT INTO reserva_subsidio(id,orcamento_id,pedido_id,programa_id,paciente_id,valor,valor_liberado,moeda,estado) VALUES (?,?,?,?,?,?,?,'BRL',?)",reservation,quote,order,program,patientId,value,released,state);}return new Covered(patientId,order,quote,2,cancellation);}
    private UUID patient(Account a){var values=jdbc.query("SELECT id FROM paciente WHERE usuario_id=?",(rs,n)->rs.getObject(1,UUID.class),a.user);if(!values.isEmpty())return values.getFirst();UUID id=UUID.randomUUID();String cpf=String.format("%011d",Math.abs(uniqueNumber()));jdbc.update("INSERT INTO paciente(id,usuario_id,cpf_cifrado,cpf_busca,nascimento,identidade_estado) VALUES (?,?,?,?,DATE '1980-01-01','VERIFICADA')",id,a.user,protector.encrypt(cpf),protector.lookup(cpf));return id;}
    private List<UUID> offerIds(Account a)throws Exception{var response=request(a,"GET","/offers",null,null,null);assertThat(response.statusCode()).as(response.body()).isEqualTo(200);return ((List<Map<String,Object>>)body(response).get("items")).stream().map(x->UUID.fromString(x.get("orderId").toString())).toList();}
    private HttpResponse<String> accept(Account a,Covered o,UUID link,String key)throws Exception{return request(a,"POST","/orders/"+o.order+"/assignment",task(link),key,String.valueOf(o.version));}
    private String task(UUID link)throws Exception{return json.writeValueAsString(Map.of("vehicleLinkId",link,"acceptedCancellationPolicyId",cancellation));}
    private HttpResponse<String> event(String value)throws Exception{return client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/integrations/payments/events")).header("Content-Type","application/octet-stream").POST(HttpRequest.BodyPublishers.ofString(value)).build(),HttpResponse.BodyHandlers.ofString());}
    private Map<String,Object> address(String city){return Map.of("street","Rua exata","number","10","district","Centro","city",city,"state","SP","postalCode","01001000","latitude",-23.55,"longitude",-46.63);}
    private byte[] protect(Object value){try{return protector.encrypt(json.writeValueAsString(value));}catch(Exception ex){throw new RuntimeException(ex);}}
    private int uniqueNumber(){return Math.abs(UUID.randomUUID().hashCode()%1_000_000)+1;}
    private HttpResponse<String> request(Account a,String method,String path,String value,String idem,String version)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).header("Content-Type","application/json");if(a!=null)b.header("Authorization","Bearer "+a.token);if(idem!=null)b.header("Idempotency-Key",idem);if(version!=null)b.header("If-Match",version);return client.send(b.method(method,value==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(value)).build(),HttpResponse.BodyHandlers.ofString());}
    private Map<String,Object> body(HttpResponse<String> r)throws Exception{return json.readValue(r.body(),new TypeReference<>(){});}
    record Account(UUID user,String token){}record Driver(UUID driver,UUID link){}record Covered(UUID patient,UUID order,UUID quote,long version,UUID cancellation){}
}
